package com.bananalab.lite;
import android.graphics.Bitmap;import org.json.*;
/** Fast preview: interpolate the actual trained output-layer logit delta over an own-model bank image. */
final class PixelRetouch{
 static Bitmap apply(Bitmap baseline,JSONArray data)throws Exception{if(data.length()!=1024)throw new IllegalArgumentException("Campo de vista previa inválido.");float[] grid=new float[1024];for(int i=0;i<grid.length;i++){grid[i]=(float)data.getDouble(i);if(Float.isNaN(grid[i])||Float.isInfinite(grid[i])||Math.abs(grid[i])>30)throw new IllegalArgumentException("Delta inválido.");}int[] pixels=new int[128*128];baseline.getPixels(pixels,0,128,0,0,128,128);for(int y=0;y<128;y++)for(int x=0;x<128;x++){int original=pixels[y*128+x];if((original>>>24)==0)continue;float gx=Math.max(0,Math.min(15,(x-3)/8f)),gy=Math.max(0,Math.min(15,(y-3)/8f));int ix=(int)gx,iy=(int)gy,nx=Math.min(15,ix+1),ny=Math.min(15,iy+1),result=0;for(int channel=0;channel<4;channel++){int shift=channel==3?24:16-channel*8;float value=((original>>>shift)&255)/255f;value=Math.max(.0001f,Math.min(.9999f,value));float a=grid[(iy*16+ix)*4+channel]*(1-(gx-ix))+grid[(iy*16+nx)*4+channel]*(gx-ix),b=grid[(ny*16+ix)*4+channel]*(1-(gx-ix))+grid[(ny*16+nx)*4+channel]*(gx-ix),delta=a*(1-(gy-iy))+b*(gy-iy);int color=Math.round(HeadTrainer.sigmoid((float)Math.log(value/(1-value))+delta)*255);if(channel==3&&color<26)color=0;result|=color<<shift;}pixels[y*128+x]=result;}return Bitmap.createBitmap(pixels,128,128,Bitmap.Config.ARGB_8888);}
}
